<?php
declare(strict_types=1);
require __DIR__.'/includes/config.php';require __DIR__.'/includes/live.php';require __DIR__.'/includes/shell.php';require __DIR__.'/includes/reptile_core.php';$uid=ir_current_user_id();
try{$pdo->exec("CREATE TABLE IF NOT EXISTS wp_ir2_finance (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,typ VARCHAR(30) NOT NULL,kategorie VARCHAR(100) NULL,castka DECIMAL(12,2) NOT NULL DEFAULT 0,datum DATE NOT NULL,zvire_id BIGINT UNSIGNED NULL,popis TEXT NULL,vytvoreno TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),INDEX(zvire_id),INDEX(datum)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");}catch(Throwable $e){}
if($_SERVER['REQUEST_METHOD']==='POST'){ir_verify_csrf();try{$op=(string)($_POST['op']??'');
 if($op==='save'){ir_require_perm('write');$ls=[];$items=(array)($_POST['line_item']??[]);foreach($items as $k=>$it)$ls[]=['item'=>$it,'qty'=>$_POST['line_qty'][$k]??1,'unit'=>$_POST['line_unit'][$k]??'','unit_price'=>$_POST['line_price'][$k]??0,'discount_pct'=>$_POST['line_disc'][$k]??0,'vat_pct'=>$_POST['line_vat'][$k]??0];
  if(!$ls&&($_POST['castka']??'')!=='')$ls[]=['item'=>trim((string)($_POST['popis']??''))?:trim((string)($_POST['kategorie']??''))?:'Položka','qty'=>1,'unit_price'=>$_POST['castka']];
  $fid=ir_finance_save($pdo,$uid,['typ'=>$_POST['typ']??'','kategorie'=>$_POST['kategorie']??'','datum'=>$_POST['datum']??'','zvire_id'=>ir_int($_POST['zvire_id']??0),'popis'=>$_POST['popis']??'','doklad'=>$_POST['doklad']??'','sold'=>!empty($_POST['sold'])],$ls,ir_int($_POST['id']??0));
  ir_flash('success','Doklad uložen.'.(!empty($_POST['sold'])&&ir_int($_POST['zvire_id']??0)?' Zvíře je označeno jako prodané (historie zůstává).':''));ir_redirect('finance.php');}
 if($op==='delete'){ir_require_perm('delete');ir_finance_delete($pdo,$uid,ir_int($_POST['id']??0));ir_flash('success','Doklad odstraněn.');ir_redirect('finance.php');}
}catch(Throwable $e){error_log('Finance: '.$e->getMessage());$error=$e instanceof PDOException?'Doklad se nepodařilo uložit. Nic nebylo zapsáno.':$e->getMessage();}}
$editFin=null;$editLines=[];if($eid=ir_int($_GET['edit']??0)){$q=$pdo->prepare('SELECT * FROM wp_ir2_finance WHERE user_id=? AND id=? AND smazano IS NULL');$q->execute([$uid,$eid]);$editFin=$q->fetch()?:null;if($editFin)$editLines=ir_finance_lines($pdo,$uid,$eid);}
$rows=[];$animals=[];$categories=[];try{
 $q=$pdo->prepare("SELECT f.*,z.jmeno_kod,z.latinsky_nazev,(SELECT COUNT(*) FROM wp_ir2_finance_lines l WHERE l.user_id=f.user_id AND l.finance_id=f.id) AS nlines FROM wp_ir2_finance f LEFT JOIN wp_ir2_zvirata z ON z.id=f.zvire_id AND z.user_id=f.user_id WHERE f.user_id=? AND f.smazano IS NULL ORDER BY f.datum DESC,f.id DESC LIMIT 300");$q->execute([$uid]);$rows=$q->fetchAll()?:[];
 $q=$pdo->prepare("SELECT id,jmeno_kod,latinsky_nazev,kupni_cena,trzni_hodnota,status_chovu FROM wp_ir2_zvirata WHERE user_id=? ORDER BY latinsky_nazev,jmeno_kod");$q->execute([$uid]);$animals=$q->fetchAll()?:[];
 $q=$pdo->prepare("SELECT COALESCE(kategorie,'Ostatní') kategorie,SUM(CASE WHEN typ='Výdaj' THEN castka ELSE 0 END) expense,SUM(CASE WHEN typ='Příjem' THEN castka ELSE 0 END) income FROM wp_ir2_finance WHERE user_id=? AND smazano IS NULL AND datum>=DATE_FORMAT(CURDATE(),'%Y-%m-01') GROUP BY COALESCE(kategorie,'Ostatní') ORDER BY expense DESC,income DESC LIMIT 8");$q->execute([$uid]);$categories=$q->fetchAll()?:[];
}catch(Throwable $e){}
$q=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN typ='Příjem' THEN castka ELSE 0 END),0) income,COALESCE(SUM(CASE WHEN typ='Výdaj' THEN castka ELSE 0 END),0) expense,COALESCE(SUM(CASE WHEN typ='Příjem' AND datum>=DATE_FORMAT(CURDATE(),'%Y-%m-01') THEN castka ELSE 0 END),0) month_income,COALESCE(SUM(CASE WHEN typ='Výdaj' AND datum>=DATE_FORMAT(CURDATE(),'%Y-%m-01') THEN castka ELSE 0 END),0) month_expense FROM wp_ir2_finance WHERE user_id=? AND smazano IS NULL");$q->execute([$uid]);$totals=$q->fetch();$income=(float)$totals['income'];$expense=(float)$totals['expense'];$monthIncome=(float)$totals['month_income'];$monthExpense=(float)$totals['month_expense'];
$purchaseValue=0.0;$marketValue=0.0;foreach($animals as $a){if(in_array((string)$a['status_chovu'],['Prodáno','Uhynulo','Archiv'],true))continue;$purchaseValue+=(float)($a['kupni_cena']??0);$marketValue+=(float)($a['trzni_hodnota']??0);}
ir_page_start('Finance','finance');if(!empty($error))echo '<div class="flash danger">'.ir_e($error).'</div>';
?>
