 <article class="mini-metric glow-panel"><span><?=ir_visual_icon('calendar')?></span><div><small>Výdaje tento měsíc</small><strong><?=number_format($monthExpense,0,',',' ')?> Kč</strong><em>provoz chovu</em></div></article>
 <article class="mini-metric glow-panel"><span><?=ir_visual_icon('animals')?></span><div><small>Pořizovací cena chovu</small><strong><?=number_format($purchaseValue,0,',',' ')?> Kč</strong><em>aktivní zvířata</em></div></article>
 <article class="mini-metric glow-panel"><span><?=ir_visual_icon('dashboard')?></span><div><small>Odhad hodnoty chovu</small><strong><?=number_format($marketValue,0,',',' ')?> Kč</strong><em>z karet zvířat</em></div></article>
</section>
<div class="finance-layout">
<section class="panel glow-panel finance-records"><header class="panel-head"><div><span class="panel-kicker">FINANCE</span><h2>Transakce</h2></div><div><strong><?=number_format($monthIncome-$monthExpense,0,',',' ')?> Kč</strong><small>bilance měsíce</small></div></header><div class="table-scroll"><table class="data-table"><thead><tr><th>Datum</th><th>Typ</th><th>Kategorie</th><th>Zvíře</th><th>Popis</th><th>Částka</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d.m.Y',strtotime((string)$r['datum']))?></td><td><span class="finance-type <?=((string)$r['typ']==='Příjem'?'income':'expense')?>"><?=ir_e((string)$r['typ'])?></span></td><td><?=ir_e((string)$r['kategorie'])?></td><td><?=ir_e((string)($r['latinsky_nazev']?:$r['jmeno_kod']?:'—'))?></td><td><?=ir_e((string)$r['popis'])?><?=(int)$r['nlines']>1?' <small class="muted">· '.(int)$r['nlines'].' položek</small>':''?></td><td><strong><?=((string)$r['typ']==='Příjem'?'+':'−')?><?=number_format((float)$r['castka'],0,',',' ')?> Kč</strong></td><td class="b1-rowact"><a class="btn tiny" href="finance.php?edit=<?=(int)$r['id']?>#fin-form">Upravit</a><form method="post" class="b1-inline-mini"><?=ir_csrf_field()?><input type="hidden" name="op" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn tiny danger" aria-label="Smazat transakci" onclick="return confirm('Smazat tuto transakci?')">×</button></form></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7"><div class="table-empty">Bez finančních záznamů.</div></td></tr><?php endif;?></tbody></table></div></section>
<aside class="finance-side">
 <form id="fin-form" class="panel glow-panel form-panel b1-fin" method="post" data-fin><?=ir_csrf_field()?><input type="hidden" name="op" value="save"><input type="hidden" name="id" value="<?=(int)($editFin['id']??0)?>"><header class="panel-head"><div><span class="panel-kicker"><?=$editFin?'ÚPRAVA DOKLADU':'NOVÝ DOKLAD'?></span><h2>Příjem / výdaj</h2></div><button class="btn primary">Uložit</button></header>
 <div class="b1-form-grid"><label>Typ<select class="input" name="typ" data-fin-type><option <?=($editFin['typ']??'')==='Výdaj'?'selected':''?>>Výdaj</option><option <?=($editFin['typ']??'')==='Příjem'?'selected':''?>>Příjem</option></select></label><label>Datum<input class="input" type="date" name="datum" value="<?=ir_e((string)($editFin['datum']??date('Y-m-d')))?>"></label><label>Kategorie<input class="input" name="kategorie" list="fin-cats" value="<?=ir_e((string)($editFin['kategorie']??''))?>" placeholder="Krmivo, technika, prodej…"></label><label>Číslo dokladu<input class="input" name="doklad" value="<?=ir_e((string)($editFin['doklad']??''))?>"></label>
 <label class="b1-wide">Zvíře (nepovinné)<select class="input" name="zvire_id"><option value="">Bez vazby</option><?php foreach($animals as $a):?><option value="<?=$a['id']?>" <?=(int)($editFin['zvire_id']??0)===(int)$a['id']?'selected':''?>><?=ir_e((string)($a['latinsky_nazev']?:$a['jmeno_kod']))?> · <?=ir_e((string)$a['jmeno_kod'])?></option><?php endforeach;?></select></label>
 <label class="b1-check b1-wide" data-fin-sold hidden><input type="checkbox" name="sold" value="1"> Prodej zvířete — označit zvíře jako prodané (karta i historie zůstanou)</label></div>
 <div class="b1-fin-lines"><div class="b1-fin-head"><span>Položka</span><span>Množ.</span><span>Jedn.</span><span>Cena/j.</span><span>Sleva %</span><span>DPH %</span><span>Celkem</span><span></span></div><div data-fin-rows>
 <?php foreach(($editLines?:[['item'=>'','qty'=>1,'unit'=>'ks','unit_price'=>'','discount_pct'=>'','vat_pct'=>'','total'=>0]]) as $l):?><div class="b1-fin-row"><input class="input" name="line_item[]" value="<?=ir_e((string)$l['item'])?>" placeholder="Např. Dubia M" aria-label="Položka"><input class="input" name="line_qty[]" value="<?=ir_e(rtrim(rtrim((string)$l['qty'],'0'),'.'))?>" inputmode="decimal" aria-label="Množství"><input class="input" name="line_unit[]" value="<?=ir_e((string)($l['unit']??''))?>" aria-label="Jednotka"><input class="input" name="line_price[]" value="<?=ir_e((string)$l['unit_price'])?>" inputmode="decimal" aria-label="Cena za jednotku"><input class="input" name="line_disc[]" value="<?=ir_e((string)($l['discount_pct']??''))?>" inputmode="decimal" aria-label="Sleva"><input class="input" name="line_vat[]" value="<?=ir_e((string)($l['vat_pct']??''))?>" inputmode="decimal" aria-label="DPH"><output>0</output><button type="button" class="b1-icon-btn danger" data-fin-del aria-label="Odebrat řádek">✕</button></div><?php endforeach;?>
 </div><div class="b1-fin-foot"><button type="button" class="btn small" data-fin-add>+ Řádek</button><strong>Celkem <span data-fin-sum>0</span> Kč</strong></div></div>
 <label class="b1-wide" style="display:block;padding:0 12px 12px">Poznámka<textarea class="input" name="popis"><?=ir_e((string)($editFin['popis']??''))?></textarea></label>
 <datalist id="fin-cats"><option>Krmivo</option><option>Technika</option><option>Vybavení</option><option>Veterinář</option><option>Zvířata — nákup</option><option>Prodej zvířat</option><option>Burzy a doprava</option><option>Energie</option></datalist>
 </form>
 <section class="panel glow-panel finance-category-summary"><header class="panel-head"><div><span class="panel-kicker">TENTO MĚSÍC</span><h2>Kategorie</h2></div></header><?php foreach($categories as $c):?><div class="finance-category-row"><span><?=ir_e((string)$c['kategorie'])?></span><strong><?=number_format((float)$c['expense'],0,',',' ')?> Kč</strong></div><?php endforeach;if(!$categories):?><p class="empty-state small">Zatím bez záznamů v tomto měsíci.</p><?php endif?></section>
