<script>
addEventListener('DOMContentLoaded',()=>{const f=document.querySelector('[data-fin]');if(!f)return;const rows=f.querySelector('[data-fin-rows]');
const num=v=>parseFloat(String(v||'').replace(',','.'))||0;
const calc=()=>{let s=0;rows.querySelectorAll('.b1-fin-row').forEach(r=>{const i=r.querySelectorAll('input');const t=num(i[1].value||1)*num(i[3].value)*(1-num(i[4].value)/100)*(1+num(i[5].value)/100);r.querySelector('output').textContent=t.toLocaleString('cs-CZ',{maximumFractionDigits:2});s+=t;});f.querySelector('[data-fin-sum]').textContent=s.toLocaleString('cs-CZ',{maximumFractionDigits:2});};
f.addEventListener('input',calc);f.querySelector('[data-fin-add]').addEventListener('click',()=>{const r=rows.lastElementChild.cloneNode(true);r.querySelectorAll('input').forEach((i,k)=>i.value=k===1?'1':(k===2?'ks':''));rows.append(r);r.querySelector('input').focus();calc();});
rows.addEventListener('click',e=>{if(e.target.closest('[data-fin-del]')&&rows.children.length>1){e.target.closest('.b1-fin-row').remove();calc();}});
const t=f.querySelector('[data-fin-type]'),a=f.querySelector('[name=zvire_id]'),sold=f.querySelector('[data-fin-sold]');const sv=()=>{sold.hidden=!(t.value==='Příjem'&&a.value);};t.addEventListener('change',sv);a.addEventListener('change',sv);sv();calc();});
</script>
